from datetime import datetime
from .settings import CONFIG

# ========== 弹幕过滤配置 ==========
# 过滤词来自 config.yml 的 danmaku_filter 分区（settings.py 统一加载）
FILTER_EXACT = set(CONFIG["danmaku_filter"]["exact_match"] or [])
FILTER_CONTAIN = CONFIG["danmaku_filter"]["contain"] or []


def is_danmaku_filtered(text: str) -> bool:
    """检查弹幕是否应被过滤（精确匹配 / 包含子串）"""
    stripped = text.strip()
    if stripped in FILTER_EXACT:
        return True
    for substr in FILTER_CONTAIN:
        if substr in text:
            return True
    return False


